{"cards": [{"node_code": "N_260707270aa8a0c7", "definition": "研究眼球表面结构（包括角膜、结膜、泪膜及睑板腺等）的生理功能、病理改变、相关疾病诊疗及表面修复技术的医学分支。", "boundary": "涵盖干眼症、角结膜炎、角膜溃疡、翼状胬肉、睑板腺功能障碍等眼表疾病。区分于眼附属器疾病（侧重眼睑、泪器、眼眶等外部结构）及眼前节疾病（侧重虹膜、睫状体等内部结构）。角膜移植等手术若主要解决眼表功能归此，若涉及深层结构需结合其他节点。", "includes": ["干眼症、角结膜炎、角膜溃疡", "翼状胬肉、睑板腺功能障碍", "眼表修复与角膜移植技术"], "excludes": ["眼睑、泪器、眼眶等外部结构疾病（主挂眼附属器疾病）", "虹膜、睫状体等眼前节内部结构疾病（主挂眼前节疾病）"], "sibling_distinctions": [{"other_code": "N_deb79e149dc33242", "rule": "眼附属器疾病侧重眼睑、泪器、眼眶等外部结构；本节点侧重角膜、结膜、泪膜等眼球表面结构。"}, {"other_code": "N_6c65ea1c27297414", "rule": "眼前节疾病侧重虹膜、睫状体等内部结构；本节点侧重角膜、结膜等表面结构。"}], "cross_boundary_rule": "角膜疾病若由全身免疫性疾病引起，主挂本节点，但需结合风湿免疫科；若由外伤引起，主挂眼外伤。"}, {"node_code": "N_deb79e149dc33242", "definition": "研究眼球外部附属结构（包括眼睑、泪器、眼眶及眼外肌等）的生理功能、病理改变、相关疾病诊疗及修复技术的医学分支。", "boundary": "涵盖眼睑炎、泪囊炎、泪道阻塞、眼眶骨折、眼外肌麻痹等眼附属器疾病。区分于眼表疾病（侧重角膜、结膜等表面结构）及眼外伤（侧重急性创伤处理）。眼眶肿瘤若涉及颅内结构需结合神经外科，但局部处理归此。", "includes": ["眼睑炎、泪囊炎、泪道阻塞", "眼眶骨折、眼外肌麻痹", "眼眶肿瘤局部处理"], "excludes": ["角膜、结膜等眼球表面结构疾病（主挂眼表疾病）", "急性眼外伤处理（主挂眼外伤）"], "sibling_distinctions": [{"other_code": "N_260707270aa8a0c7", "rule": "眼表疾病侧重角膜、结膜等表面结构；本节点侧重眼睑、泪器、眼眶等外部结构。"}, {"other_code": "N_161fdf18a4fc3ac2", "rule": "眼外伤侧重急性创伤处理；本节点侧重慢性或结构性附属器疾病。"}], "cross_boundary_rule": "眼眶肿瘤若由颅内肿瘤侵犯引起，主挂神经外科；若为原发眼眶肿瘤，主挂本节点。"}, {"node_code": "N_9b946b5b9c7cd74e", "definition": "研究眼球中层结构（包括虹膜、睫状体、脉络膜等）的生理功能、病理改变、相关疾病诊疗及修复技术的医学分支。", "boundary": "涵盖虹膜炎、睫状体炎、脉络膜炎、葡萄膜炎等葡萄膜疾病。区分于眼表疾病（侧重角膜、结膜等表面结构）及眼后节疾病（侧重视网膜、玻璃体等后部结构）。葡萄膜炎若由全身感染或免疫性疾病引起，需结合相关科室，但眼部处理归此。", "includes": ["虹膜炎、睫状体炎、脉络膜炎", "葡萄膜炎及其并发症", "葡萄膜肿瘤局部处理"], "excludes": ["角膜、结膜等眼球表面结构疾病（主挂眼表疾病）", "视网膜、玻璃体等眼后节结构疾病（主挂眼后节疾病）"], "sibling_distinctions": [{"other_code": "N_260707270aa8a0c7", "rule": "眼表疾病侧重角膜、结膜等表面结构；本节点侧重虹膜、睫状体、脉络膜等中层结构。"}, {"other_code": "N_2ee9ab46e0ddf91d", "rule": "眼后节疾病侧重视网膜、玻璃体等后部结构；本节点侧重虹膜、睫状体、脉络膜等中层结构。"}], "cross_boundary_rule": "葡萄膜炎若由全身感染（如结核、梅毒）引起，主挂本节点，但需结合感染科；若由免疫性疾病（如强直性脊柱炎）引起，需结合风湿免疫科。"}]}
